'use strict'
// boleto-pdf.js — gera PDF de boleto bancário Viacredi (AILOS 085)
// Mesma lógica de nosso número / barcode que cnab-gerar.js
//
// POST { userId, emissaoIds: [uuid, ...], contaId? }
//   → { pdfBase64, filename, totalBoletos }

const PDFDocument = require('pdfkit/js/pdfkit.standalone.js')
const { checkParentAuth } = require('./_parent-auth')

// Logo Viacredi/AILOS embutida como data URI (pdfkit standalone processa antes de chamar fs)
// 448×220 px, RGBA PNG transparente
const VIACREDI_LOGO_URI = 'data:image/png;base64,'
// VIACREDI_LOGO_URI já está definida acima — sem Buffer necessário

// Logo Itaú embutida como data URI (PNG 180×180 px)
const ITAU_LOGO_URI = 'data:image/png;base64,'

// Logo Bradesco embutida como data URI (PNG 180×180 px)
const BRADESCO_LOGO_URI = 'data:image/png;base64,'

// ══════════════════════════════════════════════════════════
//  Helpers CNAB / Barcode
// ══════════════════════════════════════════════════════════

/** Pad numérico à esquerda com zeros */
function N(v, len) {
  return String(v || '').replace(/\D/g, '').padStart(len, '0').slice(-len)
}

/** DV Módulo 10 (usado nos 3 campos da linha digitável) */
function dvMod10(s) {
  let sum = 0, w = 2
  for (let i = s.length - 1; i >= 0; i--) {
    let d = parseInt(s[i]) * w
    if (d > 9) d -= 9
    sum += d
    w = w === 2 ? 1 : 2
  }
  const r = sum % 10
  return r === 0 ? 0 : 10 - r
}

/** DV Módulo 11 do código de barras (pesos 2-9 da direita) */
function dvMod11Barcode(s) {
  const W = [2, 3, 4, 5, 6, 7, 8, 9]
  let sum = 0
  for (let i = s.length - 1, wi = 0; i >= 0; i--, wi++) {
    sum += parseInt(s[i]) * W[wi % 8]
  }
  const r = sum % 11
  if (r === 0 || r === 1 || r === 10 || r === 11) return 1
  return 11 - r
}

/**
 * Fator de vencimento (novo ciclo iniciado em 22/02/2025 = fator 1000)
 * aceita 'DD/MM/AAAA' ou 'AAAA-MM-DD[T...]'
 */
function fatorVencimento(dataStr) {
  if (!dataStr) return 0
  let d
  if (dataStr.includes('/')) {
    const [dd, mm, yyyy] = dataStr.split('/')
    d = new Date(`${yyyy}-${mm}-${dd}T12:00:00Z`)
  } else {
    d = new Date(dataStr.slice(0, 10) + 'T12:00:00Z')
  }
  const base = new Date('2025-02-22T12:00:00Z')
  return 1000 + Math.round((d - base) / 86400000)
}

// ══════════════════════════════════════════════════════════
//  Bradesco (237)
// ══════════════════════════════════════════════════════════

/** Fator de vencimento Bradesco: dias desde 07/10/1997
 *  Ciclo 1000–9999 (9000 passos), reinicia após 9999.
 */
function fatorVencimentoBradesco(dataStr) {
  if (!dataStr) return 0
  let d
  if (dataStr.includes('/')) {
    const [dd, mm, yyyy] = dataStr.split('/')
    d = new Date(`${yyyy}-${mm}-${dd}T12:00:00Z`)
  } else {
    d = new Date(dataStr.slice(0, 10) + 'T12:00:00Z')
  }
  const base = new Date('1997-10-07T12:00:00Z')
  const days = Math.round((d - base) / 86400000)
  // Mantém range 1000..9999
  return ((days - 1000) % 9000) + 1000
}

/** DV Nosso Número Bradesco — Módulo 11 "base 7"
 *  Entrada: carteira(2) + nossoNumero(11) = 13 chars
 *  Pesos: [2,7,6,5,4,3,2,7,6,5,4,3,2] da esquerda para a direita
 *  resto=0 → '0';  resto=1 → 'P';  outros → String(11 - resto)
 */
function dvNNBradesco(carteira, nn) {
  const s = N(carteira, 2) + N(nn, 11)
  const W = [2, 7, 6, 5, 4, 3, 2, 7, 6, 5, 4, 3, 2]
  let sum = 0
  for (let i = 0; i < 13; i++) sum += parseInt(s[i]) * W[i]
  const r = sum % 11
  if (r === 0) return '0'
  if (r === 1) return 'P'
  return String(11 - r)
}

/** Código de barras Bradesco 44 dígitos */
function buildBarcodeBradesco({ agencia, conta, contaDv, carteira, seq, vencimento, valor }) {
  const banco  = '237'
  const moeda  = '9'
  const fator  = fatorVencimentoBradesco(vencimento)
  const fStr   = String(fator).padStart(4, '0')
  const vCents = Math.round(
    parseFloat(String(valor).replace(/[^\d,.]/g, '').replace(',', '.')) * 100
  )
  const vStr = String(vCents).padStart(10, '0')
  const nn   = N(String(seq).replace(/\D/g, ''), 11)

  // Campo livre (25 chars): agencia(4) + carteira(2) + nossoNumero(11) + conta(7) + '0'
  const cl = N(agencia, 4) + N(carteira, 2) + nn + N(conta, 7) + '0'

  const semDV = banco + moeda + fStr + vStr + cl
  const dv    = dvMod11Barcode(semDV)
  return banco + moeda + String(dv) + fStr + vStr + cl
}

// ══════════════════════════════════════════════════════════
//  Itaú (341)
// ══════════════════════════════════════════════════════════

/** DV Nosso Número Itaú — Módulo 10
 *  Input: agencia(4) + conta(5) + carteira(3) + nossoNumero(8) = 20 chars
 */
function dvNNItau(agencia, conta, carteira, nn) {
  const s = N(agencia, 4) + N(conta, 5) + N(carteira, 3) + N(nn, 8)
  return dvMod10(s)
}

/** DV Agência/Conta Itaú — Módulo 10
 *  Input: agencia(4) + conta(5) = 9 chars
 */
function dvAgContaItau(agencia, conta) {
  return dvMod10(N(agencia, 4) + N(conta, 5))
}

/** Código de barras Itaú 44 dígitos (carteira 109)
 *  Campo livre (25): carteira(3)+nn(8)+dvNN(1)+agencia(4)+conta(5)+dvAC(1)+'000'(3)
 */
function buildBarcodeItau({ agencia, conta, carteira, seq, vencimento, valor }) {
  const banco    = '341'
  const moeda    = '9'
  const fStr     = String(fatorVencimento(vencimento)).padStart(4, '0')
  const vCents   = Math.round(
    parseFloat(String(valor).replace(/[^\d,.]/g, '').replace(',', '.')) * 100
  )
  const vStr     = String(vCents).padStart(10, '0')
  const car      = N(carteira || '109', 3)
  const nn       = N(String(seq).replace(/\D/g, ''), 8)
  const dvNN     = dvNNItau(agencia, conta, car, nn)
  const dvAC     = dvAgContaItau(agencia, conta)

  // Campo livre (25 chars): carteira(3)+nn(8)+dvNN(1)+agencia(4)+conta(5)+dvAC(1)+'000'(3)
  const cl = car + nn + String(dvNN) + N(agencia, 4) + N(conta, 5) + String(dvAC) + '000'

  const semDV = banco + moeda + fStr + vStr + cl
  const dv    = dvMod11Barcode(semDV)
  return banco + moeda + String(dv) + fStr + vStr + cl
}

// ══════════════════════════════════════════════════════════
//  Viacredi (085)
// ══════════════════════════════════════════════════════════

/**
 * Nosso número Viacredi (17 chars úteis):
 *   conta_7dig + dvConta(1) + seq_9dig
 * idêntico ao nossoNumero240() de cnab-gerar.js (sem os 3 espaços finais)
 */
function nossoNumero(conta, contaDv, seq) {
  const conta7  = N(conta, 7)
  const dv1     = String(contaDv || '0').slice(0, 1)
  const seq9    = N(String(seq).replace(/\D/g, ''), 9)
  return conta7 + dv1 + seq9   // 17 chars
}

/** Código de barras completo (44 dígitos) */
function buildBarcode({ convenio, conta, contaDv, carteira, seq, vencimento, valor }) {
  const banco  = '085'
  const moeda  = '9'
  const fator  = fatorVencimento(vencimento)
  const fStr   = String(fator).padStart(4, '0')
  const vCents = Math.round(
    parseFloat(String(valor).replace(/[^\d,.]/g, '').replace(',', '.')) * 100
  )
  const vStr   = String(vCents).padStart(10, '0')

  // Campo livre (25 chars): convenio(6) + conta7(7) + dvConta(1) + seq9(9) + '0' + carteira(1)
  const cl = N(convenio, 6) +
             N(conta, 7) +
             String(contaDv || '0').slice(0, 1) +
             N(String(seq).replace(/\D/g, ''), 9) +
             '0' +
             N(carteira || '1', 1)

  const semDV = banco + moeda + fStr + vStr + cl
  const dv    = dvMod11Barcode(semDV)
  return banco + moeda + String(dv) + fStr + vStr + cl
}

/** Linha digitável (47 dígitos formatados) */
function buildLinhaDigitavel(barcode) {
  const cl = barcode.slice(19)   // campo livre 25 chars

  // Campo 1: banco(3)+moeda(1)+cl[0..4] = 9 chars
  const c1num = barcode.slice(0, 4) + cl.slice(0, 5)
  const c1dv  = dvMod10(c1num)
  const c1    = c1num.slice(0, 5) + '.' + c1num.slice(5) + c1dv

  // Campo 2: cl[5..14] = 10 chars
  const c2num = cl.slice(5, 15)
  const c2dv  = dvMod10(c2num)
  const c2    = c2num.slice(0, 5) + '.' + c2num.slice(5) + c2dv

  // Campo 3: cl[15..24] = 10 chars
  const c3num = cl.slice(15, 25)
  const c3dv  = dvMod10(c3num)
  const c3    = c3num.slice(0, 5) + '.' + c3num.slice(5) + c3dv

  const dvGeral    = barcode[4]
  const fatorValor = barcode.slice(5, 19)

  return `${c1}  ${c2}  ${c3}  ${dvGeral}  ${fatorValor}`
}

// ══════════════════════════════════════════════════════════
//  Barcode visual ITF-25 (Interleaved 2 of 5)
// ══════════════════════════════════════════════════════════

const ITF = {
  '0':'NNWWN','1':'WNNNW','2':'NWNNW','3':'WWNNN','4':'NNWNW',
  '5':'WNWNN','6':'NWWNN','7':'NNNWW','8':'WNNWN','9':'NWNWN',
}
const N_WIDTH = 1   // narrow unit
const W_WIDTH = 3   // wide unit

function drawBarcodeITF(doc, digits, x, y, totalWidth, barHeight) {
  let s = digits
  if (s.length % 2 !== 0) s = '0' + s   // must be even

  // Build sequence of [unit, isBar] pairs
  const seq = []
  // Start: bar(1) space(1) bar(1) space(1)
  seq.push([N_WIDTH, true],[N_WIDTH, false],[N_WIDTH, true],[N_WIDTH, false])

  for (let i = 0; i < s.length; i += 2) {
    const p1 = ITF[s[i]]
    const p2 = ITF[s[i + 1]]
    for (let j = 0; j < 5; j++) {
      seq.push([p1[j] === 'W' ? W_WIDTH : N_WIDTH, true])    // bar
      seq.push([p2[j] === 'W' ? W_WIDTH : N_WIDTH, false])   // space
    }
  }
  // Stop: wide-bar(3) space(1) bar(1)
  seq.push([W_WIDTH, true],[N_WIDTH, false],[N_WIDTH, true])

  const totalUnits = seq.reduce((a, [u]) => a + u, 0)
  const unit = totalWidth / totalUnits

  let cx = x
  for (const [units, isBar] of seq) {
    const w = units * unit
    if (isBar) {
      doc.rect(cx, y, w - 0.3, barHeight).fill('#000000')
    }
    cx += w
  }
}

// ══════════════════════════════════════════════════════════
//  Formatação
// ══════════════════════════════════════════════════════════

function fmtMoney(v) {
  const n = parseFloat(String(v).replace(/[^\d,.]/g, '').replace(',', '.'))
  if (isNaN(n)) return '0,00'
  return n.toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.')
}

function fmtDate(s) {
  if (!s) return ''
  if (s.includes('/')) return s
  const p = s.slice(0, 10).split('-')
  return `${p[2]}/${p[1]}/${p[0]}`
}

function fmtCnpj(s) {
  const d = String(s || '').replace(/\D/g, '')
  if (d.length === 14) return d.replace(/(\d{2})(\d{3})(\d{3})(\d{4})(\d{2})/, '$1.$2.$3/$4-$5')
  if (d.length === 11) return d.replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1.$2.$3-$4')
  return s || ''
}

// ══════════════════════════════════════════════════════════
//  PDF — layout boleto
// ══════════════════════════════════════════════════════════

function buildPdf(boletos) {
  return new Promise((resolve, reject) => {
    const doc = new PDFDocument({ size: 'A4', margin: 0, autoFirstPage: false })
    const buffers = []
    doc.on('data', b => buffers.push(b))
    doc.on('end',  () => resolve(Buffer.concat(buffers)))
    doc.on('error', reject)
    for (const b of boletos) {
      doc.addPage()
      drawBoleto(doc, b)
    }
    doc.end()
  })
}

function drawBoleto(doc, b) {
  if ((b.bankLabel || '').toUpperCase() === 'VIACREDI') return drawBoletoViacredi(doc, b)
  const PW   = 595.28
  const PH   = 841.89
  const ML   = 36, MR = 36
  const W    = PW - ML - MR

  const BLUE  = '#004A96'
  const DGRAY = '#333333'
  const GRAY  = '#666666'
  const LGRAY = '#BBBBBB'

  function hline(y, color = LGRAY, lw = 0.4) {
    doc.moveTo(ML, y).lineTo(ML + W, y).strokeColor(color).lineWidth(lw).stroke()
  }
  function vline(x, y1, y2, color = LGRAY, lw = 0.4) {
    doc.moveTo(x, y1).lineTo(x, y2).strokeColor(color).lineWidth(lw).stroke()
  }
  function lbl(txt, x, y, w) {
    doc.font('Helvetica').fontSize(6).fillColor(GRAY)
       .text(txt, x, y, { width: w, lineBreak: false })
  }
  function val(txt, x, y, w, opts = {}) {
    doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
       .text(String(txt || ''), x, y, { width: w, lineBreak: false, ...opts })
  }
  function field(label, value, x, y, w, h = 22) {
    lbl(label, x + 2, y + 2, w - 4)
    val(value, x + 2, y + 10, w - 4)
    return y + h
  }

  let y = 36

  // ── CABEÇALHO ─────────────────────────────────────────────
  const HDR_H  = 32            // altura total do cabeçalho
  const LOGO_W = 170           // largura do painel branco do logo
  const CODE_W = 60            // largura do painel com código do banco

  // Painel branco (logo)
  doc.rect(ML, y, LOGO_W, HDR_H).fill('#FFFFFF')
  // Painel azul (código + linha digitável)
  doc.rect(ML + LOGO_W, y, W - LOGO_W, HDR_H).fill(BLUE)

  // Logo ou nome do banco
  if (b.bankLogoUri) {
    const lh = HDR_H - 8
    const lw = Math.round(lh * (b.bankLogoW || 448) / (b.bankLogoH || 220))
    const lx = ML + (LOGO_W - lw) / 2
    const ly = y + 4
    doc.image(b.bankLogoUri, lx, ly, { width: lw, height: lh })
  } else {
    doc.font('Helvetica-Bold').fontSize(11).fillColor(BLUE)
       .text(b.bankLabel || '', ML + 8, y + 10, { width: LOGO_W - 12, lineBreak: false })
  }

  // Linha separadora vertical (logo | código)
  doc.moveTo(ML + LOGO_W, y).lineTo(ML + LOGO_W, y + HDR_H)
     .strokeColor('#CCCCCC').lineWidth(0.6).stroke()

  // Código do banco
  doc.font('Helvetica-Bold').fontSize(11).fillColor('#FFFFFF')
     .text(b.bankCode || '', ML + LOGO_W + 2, y + 11,
       { width: CODE_W - 4, align: 'center', lineBreak: false })

  // Linha separadora vertical (código | linha digitável)
  doc.moveTo(ML + LOGO_W + CODE_W, y).lineTo(ML + LOGO_W + CODE_W, y + HDR_H)
     .strokeColor('rgba(255,255,255,0.4)').lineWidth(0.6).stroke()

  // Linha digitável
  const ldX = ML + LOGO_W + CODE_W + 6
  const ldW = W - LOGO_W - CODE_W - 10
  doc.font('Courier-Bold').fontSize(9.5).fillColor('#FFFFFF')
     .text(b.linhaDigitavel, ldX, y + 11, { width: ldW, align: 'right', lineBreak: false })

  y += HDR_H + 4
  hline(y, BLUE, 0.6)
  y += 2

  // ── BENEFICIÁRIO ──────────────────────────────────────────
  const colR = W * 0.30
  const colL = W - colR - 4
  lbl('BENEFICIÁRIO', ML + 2, y, colL)
  lbl('CNPJ', ML + colL + 6, y, colR)
  y += 8
  doc.font('Helvetica-Bold').fontSize(8.5).fillColor(DGRAY)
     .text(b.beneficiario, ML + 2, y, { width: colL, lineBreak: false })
  doc.font('Helvetica').fontSize(8).fillColor(DGRAY)
     .text(fmtCnpj(b.cnpj), ML + colL + 6, y, { width: colR, lineBreak: false })
  y += 14
  hline(y); y += 4

  // ── ROW: agência/convênio | nosso número | vencimento | valor ──
  const c1 = W * 0.28, c2 = W * 0.28, c3 = W * 0.18, c4 = W * 0.26
  let rx = ML
  lbl(b.agenciaLabel || 'AGÊNCIA / CONVÊNIO', rx + 2, y, c1); rx += c1
  vline(ML + c1, y, y + 24); lbl('NOSSO NÚMERO', rx + 2, y, c2); rx += c2
  vline(ML + c1 + c2, y, y + 24); lbl('VENCIMENTO', rx + 2, y, c3); rx += c3
  vline(ML + c1 + c2 + c3, y, y + 24); lbl('VALOR DO DOCUMENTO', rx + 2, y, c4)
  y += 8
  rx = ML
  doc.font('Helvetica').fontSize(8).fillColor(DGRAY)
  doc.text(b.agenciaValue || `${b.agencia} / ${b.convenio}`, rx + 2, y, { width: c1 - 4, lineBreak: false }); rx += c1
  doc.text(b.nossoNumeroFmt, rx + 2, y, { width: c2 - 4, lineBreak: false }); rx += c2
  doc.text(b.vencimento, rx + 2, y, { width: c3 - 4, lineBreak: false }); rx += c3
  doc.font('Helvetica-Bold').fontSize(8).text(`R$ ${fmtMoney(b.valor)}`, rx + 2, y, { width: c4 - 4, lineBreak: false })
  y += 14
  hline(y); y += 4

  // ── INFORMAÇÕES OPCIONAIS ─────────────────────────────────
  const infoH = 18
  const ca = W * 0.25, cb = W * 0.25, cc2 = W * 0.25, cd = W * 0.25
  rx = ML
  lbl('ESPÉCIE DOC', rx + 2, y, ca); rx += ca
  vline(ML + ca, y, y + infoH)
  lbl('ACEITE', rx + 2, y, cb); rx += cb
  vline(ML + ca + cb, y, y + infoH)
  lbl('DATA DO DOCUMENTO', rx + 2, y, cc2); rx += cc2
  vline(ML + ca + cb + cc2, y, y + infoH)
  lbl('CARTEIRA', rx + 2, y, cd)
  y += 8; rx = ML
  doc.font('Helvetica').fontSize(8).fillColor(DGRAY)
  doc.text('DS', rx + 2, y, { width: ca - 4, lineBreak: false }); rx += ca
  doc.text('N', rx + 2, y, { width: cb - 4, lineBreak: false }); rx += cb
  doc.text(b.dataDocumento, rx + 2, y, { width: cc2 - 4, lineBreak: false }); rx += cc2
  doc.text(b.carteira, rx + 2, y, { width: cd - 4, lineBreak: false })
  y += 10
  hline(y); y += 4

  // ── INSTRUÇÕES ────────────────────────────────────────────
  if (b.instrucoes) {
    lbl('INSTRUÇÕES (Texto de responsabilidade do Beneficiário)', ML + 2, y, W * 0.65)
    y += 8
    doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
       .text(b.instrucoes, ML + 2, y, { width: W * 0.65, lineBreak: true })
    y = doc.y + 4
  } else {
    y += 20
  }
  hline(y); y += 4

  // ── SACADO (PAGADOR) ──────────────────────────────────────
  lbl('PAGADOR', ML + 2, y, W * 0.65)
  lbl('CPF/CNPJ', ML + W * 0.67, y, W * 0.33)
  y += 8
  doc.font('Helvetica-Bold').fontSize(8.5).fillColor(DGRAY)
     .text(b.sacado, ML + 2, y, { width: W * 0.65, lineBreak: false })
  doc.font('Helvetica').fontSize(8).fillColor(DGRAY)
     .text(fmtCnpj(b.sacadoCpf || ''), ML + W * 0.67, y, { width: W * 0.33, lineBreak: false })
  if (b.sacadoEndereco) {
    y += 11
    doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
       .text(b.sacadoEndereco, ML + 2, y, { width: W * 0.75, lineBreak: false })
  }
  y += 14
  hline(y, BLUE, 0.8); y += 10

  // ── CÓDIGO DE BARRAS ──────────────────────────────────────
  // Posição fixa na parte inferior
  const bcY = PH - 100
  const bcH = 55

  // Linha de corte (tracejada)
  doc.moveTo(ML, bcY - 14).lineTo(ML + W, bcY - 14)
     .strokeColor(LGRAY).lineWidth(0.5).dash(4, { space: 4 }).stroke()
  doc.undash()
  doc.font('Helvetica').fontSize(6).fillColor(GRAY)
     .text('↓  CORTE AQUI  ↓', ML + W / 2 - 30, bcY - 24, { width: 80, lineBreak: false })

  // Barcode
  drawBarcodeITF(doc, b.barcode, ML + 8, bcY, W - 16, bcH)

  // Linha digitável abaixo do barcode
  doc.font('Courier').fontSize(10).fillColor(DGRAY)
     .text(b.linhaDigitavel, ML, bcY + bcH + 6, { width: W, align: 'center', lineBreak: false })
}

// ══════════════════════════════════════════════════════════
//  PDF — layout boleto Viacredi (3 seções conforme modelo)
// ══════════════════════════════════════════════════════════

function drawBoletoViacredi(doc, b) {
  const PW    = 595.28
  const ML    = 36
  const W     = PW - ML - 36   // 523.28

  const DGRAY = '#333333'
  const GRAY  = '#777777'
  const LGRAY = '#CCCCCC'
  const BLACK = '#000000'

  function hline(y, color, lw) {
    doc.moveTo(ML, y).lineTo(ML + W, y)
       .strokeColor(color || LGRAY).lineWidth(lw || 0.4).stroke()
  }
  function vline(x, y1, y2) {
    doc.moveTo(x, y1).lineTo(x, y2)
       .strokeColor(LGRAY).lineWidth(0.4).stroke()
  }
  function lbl(txt, x, y, w) {
    doc.font('Helvetica').fontSize(6).fillColor(GRAY)
       .text(txt, x, y, { width: w, lineBreak: false })
  }
  function val(txt, x, y, w) {
    doc.font('Helvetica').fontSize(8).fillColor(DGRAY)
       .text(String(txt || ''), x, y, { width: w, lineBreak: false })
  }
  function valB(txt, x, y, w) {
    doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
       .text(String(txt || ''), x, y, { width: w, lineBreak: false })
  }
  function valR(txt, x, y, w) {
    doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
       .text(String(txt || ''), x, y, { width: w, align: 'right', lineBreak: false })
  }

  let y = 36

  // ══════════════════════════════════════════════════════════
  //  RECIBO DO BENEFICIÁRIO
  // ══════════════════════════════════════════════════════════
  doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
     .text('Recibo do Beneficiário', ML, y, { width: W, lineBreak: false })
  y += 12
  hline(y); y += 2

  const rcbSplit = W * 0.56
  const rcbRW   = W - rcbSplit
  const rcbRX   = ML + rcbSplit + 4

  const leftRows = [
    ['Beneficiário:',         b.beneficiario      || ''],
    ['Pagador:',              b.sacado            || ''],
    ['Nº Documento:',         b.numeroDocumento   || ''],
    ['Nosso Número:',         b.nossoNumeroDisplay || b.nossoNumeroFmt],
    ['Vencimento:',           b.vencimento        || ''],
    ['Banco:',                b.bankCode          || ''],
    ['Agência/Beneficiário:', b.agenciaCodigo     || b.agenciaValue],
    ['Valor Documento:',      `R$ ${fmtMoney(b.valor)}`],
  ]
  const rStartY = y
  for (const [label, value] of leftRows) {
    doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
       .text(label, ML + 2, y, { width: 74, lineBreak: false })
    doc.font('Helvetica').fontSize(8).fillColor(DGRAY)
       .text(value, ML + 78, y, { width: rcbSplit - 82, lineBreak: false })
    y += 12
  }

  let ry = rStartY
  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('Recebi este documento em _____ / _____ / _____________', rcbRX, ry, { width: rcbRW - 8, lineBreak: false })
  ry += 30
  doc.moveTo(rcbRX, ry).lineTo(ML + W, ry).strokeColor(LGRAY).lineWidth(0.3).stroke()
  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('Assinatura do Pagador', rcbRX, ry + 2, { width: rcbRW - 8, align: 'center', lineBreak: false })
  ry += 20
  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('(=) Valor Cobrado', rcbRX, ry, { width: rcbRW * 0.56, lineBreak: false })
  doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
     .text(`R$ ${fmtMoney(b.valor)}`, rcbRX + rcbRW * 0.56, ry, { width: rcbRW * 0.44 - 8, align: 'right', lineBreak: false })
  ry += 12
  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('(=) Valor do Documento', rcbRX, ry, { width: rcbRW * 0.56, lineBreak: false })
  doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
     .text(`R$ ${fmtMoney(b.valor)}`, rcbRX + rcbRW * 0.56, ry, { width: rcbRW * 0.44 - 8, align: 'right', lineBreak: false })
  ry += 14

  vline(ML + rcbSplit, rStartY - 2, Math.max(y, ry))
  y = Math.max(y, ry) + 2
  hline(y); y += 2

  // ── corte 1 ───────────────────────────────────────────────
  y += 6
  doc.moveTo(ML, y).lineTo(ML + W, y)
     .strokeColor(LGRAY).lineWidth(0.5).dash(4, { space: 4 }).stroke()
  doc.undash()
  doc.font('Helvetica').fontSize(6).fillColor(GRAY)
     .text('Corte na linha pontilhada', ML, y - 8, { width: W, align: 'center', lineBreak: false })
  y += 8

  // ── linha digitável standalone ────────────────────────────
  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('Linha digitável para ser utilizada em seu Internet Banking', ML, y, { width: W, lineBreak: false })
  y += 9
  doc.font('Courier-Bold').fontSize(10).fillColor(BLACK)
     .text(b.linhaDigitavel, ML, y, { width: W, lineBreak: false })
  y += 14

  // ══════════════════════════════════════════════════════════
  //  RECIBO DO PAGADOR
  // ══════════════════════════════════════════════════════════
  const HDR_H  = 32
  const LOGO_W = 170
  const CODE_W = 55

  hline(y, LGRAY, 0.5)
  if (b.bankLogoUri) {
    const lh = HDR_H - 8
    const lw = Math.round(lh * (b.bankLogoW || 448) / (b.bankLogoH || 220))
    doc.image(b.bankLogoUri, ML + (LOGO_W - lw) / 2, y + 4, { width: lw, height: lh })
  } else {
    doc.font('Helvetica-Bold').fontSize(11).fillColor(DGRAY)
       .text(b.bankLabel || '', ML + 8, y + 10, { width: LOGO_W - 16, lineBreak: false })
  }
  vline(ML + LOGO_W, y, y + HDR_H)
  doc.font('Helvetica-Bold').fontSize(11).fillColor(DGRAY)
     .text(b.bankCode || '', ML + LOGO_W + 2, y + 11, { width: CODE_W - 4, align: 'center', lineBreak: false })
  vline(ML + LOGO_W + CODE_W, y, y + HDR_H)
  doc.font('Helvetica-Bold').fontSize(13).fillColor(DGRAY)
     .text('RECIBO DO PAGADOR', ML + LOGO_W + CODE_W + 6, y + 10,
       { width: W - LOGO_W - CODE_W - 10, align: 'right', lineBreak: false })
  y += HDR_H
  hline(y, LGRAY, 0.5); y += 2

  // row 1
  const rp1 = W * 0.38, rp2 = W * 0.22, rp3 = W * 0.09, rp4 = W * 0.11
  const rp5 = W - rp1 - rp2 - rp3 - rp4
  let rx = ML
  lbl('Nome do Beneficiário', rx + 2, y + 2, rp1 - 4); rx += rp1
  vline(ML + rp1, y, y + 22)
  lbl('Agência / Código Beneficiário', rx + 2, y + 2, rp2 - 4); rx += rp2
  vline(ML + rp1 + rp2, y, y + 22)
  lbl('Espécie', rx + 2, y + 2, rp3 - 4); rx += rp3
  vline(ML + rp1 + rp2 + rp3, y, y + 22)
  lbl('Quantidade', rx + 2, y + 2, rp4 - 4); rx += rp4
  vline(ML + rp1 + rp2 + rp3 + rp4, y, y + 22)
  lbl('Nosso Número', rx + 2, y + 2, rp5 - 4)
  y += 9; rx = ML
  val(b.beneficiario, rx + 2, y, rp1 - 4); rx += rp1
  val(b.agenciaCodigo || b.agenciaValue, rx + 2, y, rp2 - 4); rx += rp2
  val('R$', rx + 2, y, rp3 - 4); rx += rp3
  val('', rx + 2, y, rp4 - 4); rx += rp4
  val(b.nossoNumeroDisplay || b.nossoNumeroFmt, rx + 2, y, rp5 - 4)
  y += 13; hline(y); y += 2

  // row 2
  const rq1 = W * 0.15, rq2 = W * 0.15, rq3 = W * 0.22, rq4 = W * 0.18
  const rq5 = W - rq1 - rq2 - rq3 - rq4
  rx = ML
  lbl('Número do Documento', rx + 2, y + 2, rq1 - 4); rx += rq1
  vline(ML + rq1, y, y + 22)
  lbl('Contrato', rx + 2, y + 2, rq2 - 4); rx += rq2
  vline(ML + rq1 + rq2, y, y + 22)
  lbl('CNPJ/CPF', rx + 2, y + 2, rq3 - 4); rx += rq3
  vline(ML + rq1 + rq2 + rq3, y, y + 22)
  lbl('Vencimento', rx + 2, y + 2, rq4 - 4); rx += rq4
  vline(ML + rq1 + rq2 + rq3 + rq4, y, y + 22)
  lbl('Valor do Documento', rx + 2, y + 2, rq5 - 4)
  y += 9; rx = ML
  val(b.numeroDocumento || '', rx + 2, y, rq1 - 4); rx += rq1
  val('', rx + 2, y, rq2 - 4); rx += rq2
  val(fmtCnpj(b.cnpj), rx + 2, y, rq3 - 4); rx += rq3
  val(b.vencimento, rx + 2, y, rq4 - 4); rx += rq4
  valR(`R$ ${fmtMoney(b.valor)}`, rx + 2, y, rq5 - 4)
  y += 13; hline(y); y += 2

  // row 3: pagador (blank)
  lbl('Pagador', ML + 2, y + 2, W - 4)
  y += 20; hline(y); y += 2

  // row 4: informações
  lbl('Informações', ML + 2, y + 2, 55)
  doc.font('Helvetica').fontSize(7).fillColor(DGRAY)
     .text('NÃO COBRAR QUALQUER TARIFA DE EMISSÃO DE CARNÊ/BOLETO OU OUTRA(S) TAXA(S) SEMELHANTE(S)',
       ML + 58, y + 2, { width: W - 62, lineBreak: false })
  y += 11
  doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
     .text(b.agenciaCodigo || b.agenciaValue, ML + 2, y, { lineBreak: false })
  y += 10
  doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
     .text(b.numeroDocumento || '', ML + 2, y, { lineBreak: false })
  y += 10; hline(y); y += 2

  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('Autenticação Mecânica', ML, y + 4, { width: W, align: 'right', lineBreak: false })
  y += 14

  // ── corte 2 ───────────────────────────────────────────────
  y += 4
  doc.moveTo(ML, y).lineTo(ML + W, y)
     .strokeColor(LGRAY).lineWidth(0.5).dash(4, { space: 4 }).stroke()
  doc.undash()
  doc.font('Helvetica').fontSize(6).fillColor(GRAY)
     .text('Corte na linha pontilhada', ML, y - 8, { width: W, align: 'center', lineBreak: false })
  y += 8

  // ══════════════════════════════════════════════════════════
  //  FICHA DE COMPENSAÇÃO
  // ══════════════════════════════════════════════════════════
  hline(y, LGRAY, 0.5)
  if (b.bankLogoUri) {
    const lh = HDR_H - 8
    const lw = Math.round(lh * (b.bankLogoW || 448) / (b.bankLogoH || 220))
    doc.image(b.bankLogoUri, ML + (LOGO_W - lw) / 2, y + 4, { width: lw, height: lh })
  } else {
    doc.font('Helvetica-Bold').fontSize(11).fillColor(DGRAY)
       .text(b.bankLabel || '', ML + 8, y + 10, { width: LOGO_W - 16, lineBreak: false })
  }
  vline(ML + LOGO_W, y, y + HDR_H)
  doc.font('Helvetica-Bold').fontSize(11).fillColor(DGRAY)
     .text(b.bankCode || '', ML + LOGO_W + 2, y + 11, { width: CODE_W - 4, align: 'center', lineBreak: false })
  vline(ML + LOGO_W + CODE_W, y, y + HDR_H)
  doc.font('Courier-Bold').fontSize(8).fillColor(DGRAY)
     .text(b.linhaDigitavel, ML + LOGO_W + CODE_W + 6, y + 11,
       { width: W - LOGO_W - CODE_W - 10, align: 'right', lineBreak: false })
  y += HDR_H; hline(y, LGRAY, 0.5); y += 2

  // local pagamento | vencimento
  const lpW = W * 0.68, vncW = W - W * 0.68
  lbl('Local de Pagamento', ML + 2, y + 2, lpW - 4)
  vline(ML + lpW, y, y + 22)
  lbl('Vencimento', ML + lpW + 2, y + 2, vncW - 4)
  y += 9
  doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
     .text('Pagar preferencialmente nas cooperativas do Sistema AILOS.', ML + 2, y, { width: lpW - 4, lineBreak: false })
  valR(b.vencimento, ML + lpW + 2, y, vncW - 4)
  y += 13; hline(y); y += 2

  // beneficiário | cnpj | agência/código
  const bfW = W * 0.42, cnW = W * 0.22, agW = W - W * 0.42 - W * 0.22
  lbl('Beneficiário', ML + 2, y + 2, bfW - 4)
  vline(ML + bfW, y, y + 22)
  lbl('CNPJ/CPF', ML + bfW + 2, y + 2, cnW - 4)
  vline(ML + bfW + cnW, y, y + 22)
  lbl('Agência / Código Beneficiário', ML + bfW + cnW + 2, y + 2, agW - 4)
  y += 9
  valB(b.beneficiario, ML + 2, y, bfW - 4)
  val(fmtCnpj(b.cnpj), ML + bfW + 2, y, cnW - 4)
  val(b.agenciaCodigo || b.agenciaValue, ML + bfW + cnW + 2, y, agW - 4)
  y += 13; hline(y); y += 2

  // data doc | nº doc | espécie | aceite | data proc | nosso número
  const dd1=W*0.14, dd2=W*0.14, dd3=W*0.09, dd4=W*0.07, dd5=W*0.15
  const dd6 = W - dd1 - dd2 - dd3 - dd4 - dd5
  rx = ML
  lbl('Data do Documento', rx+2, y+2, dd1-4); rx+=dd1; vline(ML+dd1, y, y+22)
  lbl('Nº do Documento', rx+2, y+2, dd2-4); rx+=dd2; vline(ML+dd1+dd2, y, y+22)
  lbl('Espécie Doc.', rx+2, y+2, dd3-4); rx+=dd3; vline(ML+dd1+dd2+dd3, y, y+22)
  lbl('Aceite', rx+2, y+2, dd4-4); rx+=dd4; vline(ML+dd1+dd2+dd3+dd4, y, y+22)
  lbl('Data de Processamento', rx+2, y+2, dd5-4); rx+=dd5; vline(ML+dd1+dd2+dd3+dd4+dd5, y, y+22)
  lbl('Nosso Número / Cód. do Documento', rx+2, y+2, dd6-4)
  y += 9; rx = ML
  val(b.dataDocumento, rx+2, y, dd1-4); rx+=dd1
  val(b.numeroDocumento||'', rx+2, y, dd2-4); rx+=dd2
  val('N', rx+2, y, dd3-4); rx+=dd3
  val('S', rx+2, y, dd4-4); rx+=dd4
  val(b.dataDocumento, rx+2, y, dd5-4); rx+=dd5
  val(b.nossoNumeroDisplay||b.nossoNumeroFmt, rx+2, y, dd6-4)
  y += 13; hline(y); y += 2

  // uso banco | carteira | esp moeda | qtd moeda | val moeda | valor doc
  const finW = W * 0.30, ubL = W - W * 0.30
  const ub1=ubL*0.17, ub2=ubL*0.14, ub3=ubL*0.14, ub4=ubL*0.28, ub5=ubL*0.27
  rx = ML
  lbl('Uso do Banco', rx+2, y+2, ub1-4); rx+=ub1; vline(ML+ub1, y, y+22)
  lbl('Carteira', rx+2, y+2, ub2-4); rx+=ub2; vline(ML+ub1+ub2, y, y+22)
  lbl('Espécie Moeda', rx+2, y+2, ub3-4); rx+=ub3; vline(ML+ub1+ub2+ub3, y, y+22)
  lbl('Quantidade Moeda', rx+2, y+2, ub4-4); rx+=ub4; vline(ML+ub1+ub2+ub3+ub4, y, y+22)
  lbl('Valor Moeda', rx+2, y+2, ub5-4)
  vline(ML+ubL, y, y+22)
  lbl('(=) Valor do Documento', ML+ubL+2, y+2, finW-4)
  y += 9; rx = ML
  val('', rx+2, y, ub1-4); rx+=ub1
  val(b.carteira||'01', rx+2, y, ub2-4); rx+=ub2
  val('R$', rx+2, y, ub3-4); rx+=ub3
  val('', rx+2, y, ub4-4); rx+=ub4
  val('', rx+2, y, ub5-4)
  valR(`R$ ${fmtMoney(b.valor)}`, ML+ubL+2, y, finW-4)
  y += 13; hline(y); y += 2

  // instruções (esq) + financeiro (dir)
  const instrY = y
  const instrW = W - finW
  const finX   = ML + instrW
  const instrH = 6 * 16   // 96pt = 6 itens × 16pt

  lbl('Instruções', ML + 2, instrY + 2, instrW - 4)
  vline(finX, instrY, instrY + instrH)

  if (b.instrucoes) {
    doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
       .text(b.instrucoes, ML + 2, instrY + 10, {
         width: instrW - 8,
         height: instrH - 14,
         lineBreak: true,
       })
  }

  const finItems = [
    ['(=) Valor do Documento',    `R$ ${fmtMoney(b.valor)}`],
    ['(-) Desconto / Abatimento', 'R$ 0,00'],
    ['(-) Outras Deduções',       'R$ 0,00'],
    ['(+) Mora / Multa',          'R$ 0,00'],
    ['(+) Outros Acréscimos',     ''],
    ['(=) Valor Cobrado',         `R$ ${fmtMoney(b.valor)}`],
  ]
  let fy = instrY
  for (const [label, amount] of finItems) {
    lbl(label, finX + 2, fy + 2, finW - 4)
    if (amount) valR(amount, finX + 2, fy + 9, finW - 4)
    fy += 16
    if (fy < instrY + instrH) {
      doc.moveTo(finX, fy).lineTo(ML + W, fy).strokeColor(LGRAY).lineWidth(0.3).stroke()
    }
  }
  y = instrY + instrH + 2; hline(y); y += 2

  // pagador
  lbl('Pagador', ML + 2, y + 2, W - 4)
  y += 9
  doc.font('Helvetica-Bold').fontSize(8).fillColor(DGRAY)
     .text(`${b.sacado}${b.sacadoCpf ? ' - ' + fmtCnpj(b.sacadoCpf) : ''}`, ML + 2, y, { width: W - 4, lineBreak: false })
  y += 10
  if (b.sacadoEndereco) {
    doc.font('Helvetica').fontSize(7.5).fillColor(DGRAY)
       .text(b.sacadoEndereco, ML + 2, y, { width: W - 4, lineBreak: false })
    y += 10
  }
  y += 4; hline(y); y += 2

  // beneficiário | final | código de baixa
  const bx1 = W * 0.50, bx2 = W * 0.20, bx3 = W * 0.30
  lbl('Beneficiário', ML + 2, y + 2, bx1 - 4)
  vline(ML + bx1, y, y + 18)
  lbl('Final', ML + bx1 + 2, y + 2, bx2 - 4)
  vline(ML + bx1 + bx2, y, y + 18)
  lbl('Código de Baixa', ML + bx1 + bx2 + 2, y + 2, bx3 - 4)
  y += 18; hline(y); y += 4

  // código de barras
  const bcH = 50
  drawBarcodeITF(doc, b.barcode, ML + 4, y, W * 0.56, bcH)

  doc.font('Helvetica').fontSize(6.5).fillColor(GRAY)
     .text('Autenticação Mecânica', ML + W * 0.60, y + 2, { width: W * 0.20, lineBreak: false })
  doc.font('Helvetica-Bold').fontSize(10).fillColor(DGRAY)
     .text('FICHA DE COMPENSAÇÃO', ML + W * 0.60, y + 14, { width: W * 0.40 - 4, align: 'right', lineBreak: false })

  hline(y + bcH + 6, LGRAY)
}


// ══════════════════════════════════════════════════════════
//  Supabase helper
// ══════════════════════════════════════════════════════════

async function sbFetch(url, key, path, method = 'GET', body = null) {
  const opts = {
    method,
    headers: {
      apikey: key,
      Authorization: `Bearer ${key}`,
      'Content-Type': 'application/json',
      Accept: 'application/json',
      Prefer: 'return=representation',
    },
  }
  if (body) opts.body = JSON.stringify(body)
  const r = await fetch(`${url}/rest/v1/${path}`, opts)
  if (!r.ok) {
    const txt = await r.text().catch(() => '')
    throw new Error(`Supabase [${method} ${path}]: ${r.status} ${txt}`)
  }
  return r.json()
}

// ══════════════════════════════════════════════════════════
//  Handler
// ══════════════════════════════════════════════════════════

exports.handler = async (event) => {
  try {
    return await handle(event)
  } catch (err) {
    console.error('[boleto-pdf]', err?.message)
    return { statusCode: 500, body: JSON.stringify({ error: err?.message }) }
  }
}

async function handle(event) {
  const SB_URL = process.env.SUPABASE_URL
  const SB_KEY = process.env.SUPABASE_SERVICE_KEY
  if (!SB_URL || !SB_KEY) {
    return { statusCode: 500, body: JSON.stringify({ error: 'Supabase não configurado' }) }
  }

  let userId, emissaoIds, contaId, vencimentoParam
  if (event.httpMethod === 'POST') {
    const b = JSON.parse(event.body || '{}')
    userId         = b.userId
    emissaoIds     = b.emissaoIds || (b.emissaoId ? [b.emissaoId] : [])
    contaId        = b.contaId
    vencimentoParam = b.vencimento || ''
  } else {
    userId         = event.queryStringParameters?.userId
    emissaoIds     = (event.queryStringParameters?.emissaoIds || '').split(',').filter(Boolean)
    contaId        = event.queryStringParameters?.contaId
    vencimentoParam = event.queryStringParameters?.vencimento || ''
  }

  if (!userId || !Array.isArray(emissaoIds) || emissaoIds.length === 0) {
    return { statusCode: 400, body: JSON.stringify({ error: 'userId e emissaoIds são obrigatórios' }) }
  }

  const authError = await checkParentAuth(event, userId)
  if (authError) return authError

  // ── Busca perfil (cnab_config + dados do beneficiário) ────
  const profiles = await sbFetch(SB_URL, SB_KEY,
    `profiles?id=eq.${userId}&select=company_name,cnpj,cnab_config`
  )
  const profile = profiles[0] || {}

  // Seleciona conta bancária (mesma lógica de cnab-gerar.js)
  let contas = []
  const rawCfg = profile.cnab_config
  if (Array.isArray(rawCfg)) {
    contas = rawCfg
  } else if (rawCfg && typeof rawCfg === 'object') {
    contas = [{ id: 'legacy', banco: rawCfg.banco || 'bradesco', label: 'Bradesco', ...rawCfg }]
  }

  let cc
  if (contaId) {
    cc = contas.find(c => c.id === contaId)
  } else if (contas.length === 1) {
    cc = contas[0]
  }
  if (!cc) {
    return { statusCode: 422, body: JSON.stringify({ error: 'Conta bancária não encontrada. Informe contaId.' }) }
  }

  const banco = (cc.banco || 'viacredi').toLowerCase()
  const isBradesco = banco === 'bradesco'
  const isItau     = banco === 'itau'
  const isViacredi = banco === 'viacredi'
  if (!isBradesco && !isItau && !isViacredi) {
    return { statusCode: 422, body: JSON.stringify({ error: `boleto-pdf.js suporta Viacredi, Bradesco e Itaú. Banco configurado: ${banco}` }) }
  }

  // ── Busca emissões ────────────────────────────────────────
  const ids = emissaoIds.map(id => `"${id}"`).join(',')
  const emissoes = await sbFetch(SB_URL, SB_KEY,
    `nfse_emissoes?id=in.(${ids})&user_id=eq.${userId}` +
    `&select=id,numero_nfse,numero_dps,tomador_nome,valor_servico,created_at,competencia,cob_data_json,vencimento_boleto`
  )

  if (!emissoes || emissoes.length === 0) {
    return { statusCode: 404, body: JSON.stringify({ error: 'Nenhuma emissão encontrada.' }) }
  }

  // ── Monta dados de cada boleto ────────────────────────────
  const hoje = new Date()
  const dataHoje = `${String(hoje.getDate()).padStart(2,'0')}/${String(hoje.getMonth()+1).padStart(2,'0')}/${hoje.getFullYear()}`

  const boletos = emissoes.map((em, idx) => {
    const cob    = em.cob_data_json || {}
    const seq    = em.numero_nfse || em.numero_dps || String(idx + 1)
    // Prioridade: param body > vencimento_boleto salvo > cob_data_json > hoje+30d
    const vencBase = vencimentoParam || em.vencimento_boleto || cob.vencimento || cob.dataVencimento || ''
    let venc = vencBase
    if (!venc) {
      const d30 = new Date(); d30.setDate(d30.getDate() + 30)
      venc = d30.toISOString().slice(0, 10)
    }
    const valor  = em.valor_servico || cob.totalValue || 0
    const sacado = em.tomador_nome || cob.tenant || ''

    let barcode, nossoNumeroFmt, agenciaLabel, agenciaValue, bankCode, bankLabel, bankLogoUri, bankLogoW, bankLogoH
    let nossoNumeroDisplay, agenciaCodigo, numeroDocumento

    if (isBradesco) {
      // ── Bradesco (237) ──
      const carteira = N(cc.carteira || '09', 2)
      const nn       = N(String(seq).replace(/\D/g, ''), 11)
      const nnDv     = dvNNBradesco(carteira, nn)

      barcode = buildBarcodeBradesco({
        agencia:  cc.agencia,
        conta:    cc.conta,
        contaDv:  cc.conta_dv || '0',
        carteira,
        seq,
        vencimento: venc,
        valor,
      })

      nossoNumeroFmt = `${carteira}/${nn}-${nnDv}`
      agenciaLabel   = 'AGÊNCIA / CÓD. CEDENTE'
      agenciaValue   = `${N(cc.agencia, 4)}-${cc.agencia_dv || '0'} / ${N(cc.conta, 7)}-${cc.conta_dv || '0'}`
      bankCode       = '237-2'
      bankLabel      = 'BRADESCO'
      bankLogoUri    = null
      bankLogoW      = 0
      bankLogoH      = 0
    } else if (isItau) {
      // ── Itaú (341) ──
      const carteira = cc.carteira || '109'
      const nn       = N(String(seq).replace(/\D/g, ''), 8)
      const dvNN     = dvNNItau(cc.agencia, cc.conta, N(carteira, 3), nn)
      const dvAC     = dvAgContaItau(cc.agencia, cc.conta)

      barcode = buildBarcodeItau({
        agencia:    cc.agencia,
        conta:      cc.conta,
        carteira,
        seq,
        vencimento: venc,
        valor,
      })

      nossoNumeroFmt = `${N(carteira, 3)}/${nn}-${dvNN}`
      agenciaLabel   = 'AGÊNCIA / CONTA'
      agenciaValue   = `${N(cc.agencia, 4)}-${cc.agencia_dv || '0'} / ${N(cc.conta, 5)}-${cc.conta_dv || '0'}`
      bankCode       = '341-7'
      bankLabel      = 'ITAÚ'
      bankLogoUri    = ITAU_LOGO_URI || null
      bankLogoW      = 180
      bankLogoH      = 180
    } else {
      // ── Viacredi (085) ──
      barcode = buildBarcode({
        convenio:  cc.convenio  || '101004',
        conta:     cc.conta,
        contaDv:   cc.conta_dv  || '0',
        carteira:  cc.carteira  || '1',
        seq,
        vencimento: venc,
        valor,
      })

      nossoNumeroFmt    = `${N(cc.conta, 7)}-${cc.conta_dv || '0'} / ${N(String(seq).replace(/\D/g,''), 9)}`
      agenciaLabel      = 'AGÊNCIA / CONVÊNIO'
      agenciaValue      = `${cc.agencia ? `${N(cc.agencia, 5)}-${cc.agencia_dv || '0'}` : ''} / ${cc.convenio || '101004'}`
      bankCode          = '085-0'
      bankLabel         = 'VIACREDI'
      bankLogoUri       = VIACREDI_LOGO_URI || null
      bankLogoW         = 448
      bankLogoH         = 220
      // Viacredi-specific display fields (used by drawBoletoViacredi)
      nossoNumeroDisplay = N(cc.conta, 7) + (cc.conta_dv || '0') + N(String(seq).replace(/\D/g,''), 9)
      agenciaCodigo      = `${N(cc.agencia || '0', 4)}-${cc.agencia_dv || '0'}/${N(cc.conta, 7)}-${cc.conta_dv || '0'}`
      numeroDocumento    = String(seq)
    }

    return {
      beneficiario:    profile.company_name || '',
      cnpj:            profile.cnpj || '',
      agencia:         cc.agencia ? `${N(cc.agencia, 5)}-${cc.agencia_dv || '0'}` : '',
      convenio:        cc.convenio || '',
      nossoNumeroFmt,
      nossoNumeroDisplay,
      agenciaCodigo,
      numeroDocumento,
      carteira:        cc.carteira || (isBradesco ? '09' : '1'),
      vencimento:      fmtDate(venc),
      valor,
      dataDocumento:   dataHoje,
      sacado,
      sacadoCpf:       cob.cpf || '',
      sacadoEndereco:  cob.property || cob.endereco || '',
      instrucoes: cc.instrucao || (() => {
        const linhas = []
        if (cc.mora_cod && cc.mora_cod !== '3') {
          if (cc.mora_cod === '2')
            linhas.push(`Juros de ${cc.mora_val}% ao mês após o vencimento`)
          else if (cc.mora_cod === '1')
            linhas.push(`Juros de R$ ${String(cc.mora_val||'0').replace('.',',')} por dia após o vencimento`)
        }
        if (cc.multa_cod && cc.multa_cod !== '0') {
          if (cc.multa_cod === '1')
            linhas.push(`Multa de R$ ${String(cc.multa_val||'0').replace('.',',')} após o vencimento`)
          else if (cc.multa_cod === '2')
            linhas.push(`Multa de ${cc.multa_val}% após o vencimento`)
        }
        if (cc.protesto_cod === '1')
          linhas.push(`Protesto automático em ${cc.protesto_prazo || '5'} dias corridos após o vencimento`)
        const base = cob.instrucoes ||
          (`Referente a: ${em.competencia || cob.mesRef || ''}` +
           (cob.property ? `\nImóvel: ${cob.property}` : ''))
        return linhas.length ? linhas.join('\n') + '\n' + base : base
      })(),
      barcode,
      linhaDigitavel:  buildLinhaDigitavel(barcode),
      // Bank display
      bankCode,
      bankLabel,
      bankLogoUri,
      bankLogoW,
      bankLogoH,
      agenciaLabel,
      agenciaValue,
    }
  })

  // ── Gera PDF ──────────────────────────────────────────────
  const pdfBuf  = await buildPdf(boletos)
  const dd      = String(hoje.getDate()).padStart(2, '0')
  const mm      = String(hoje.getMonth() + 1).padStart(2, '0')
  const filename = `boleto_${dd}${mm}${hoje.getFullYear()}_${emissaoIds[0].slice(0, 8)}.pdf`

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      pdfBase64:    pdfBuf.toString('base64'),
      filename,
      totalBoletos: boletos.length,
    }),
  }
}
